  min_dex = EXCLUDED.min_dex,
  min_con = EXCLUDED.min_con,
  min_chr = EXCLUDED.min_chr,
  xpadjustment = EXCLUDED.xpadjustment,
  armor = EXCLUDED.armor,
  weapons = EXCLUDED.weapons,
  description = EXCLUDED.description,
