INSERT INTO public.races (id, name, avgweight, avgheight, min_str, min_int, min_wis, min_dex, min_con, min_chr, max_str, max_int, max_wis, max_dex, max_con, max_chr, xpadjustment, armor, weapons, description, rangedbonus, max_hd, modified, hd_mod, ruleset_id) VALUES (5, 'Human', 175, 72, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 10, NULL, NULL, 'Humans come in a broad variety of shapes and sizes; the Game Master must decide what sorts of Humans live in the game world. An average Human male in good health stands around six feet tall and weighs about 175 pounds. Most Humans live around 75 years.

Restrictions: Humans may be any single class. They have no minimum or maximum ability score requirements. 

Special Abilities: Humans learn unusually quickly, gaining a bonus of 10% to all experience points earned.

Saving Throws: Humans are the ?standard,? and thus have no saving throw bonuses.', NULL, NULL, '2021-09-14 00:23:27.000+00'::timestamp, NULL, (SELECT id FROM public.ruleset WHERE name = 'Basic Fantasy Enhanced' LIMIT 1))
