  ruleset_id = EXCLUDED.ruleset_id;

INSERT INTO public.spells (id, name, "range", duration, description, modified, ruleset_id) VALUES (20, 'Death Spell', '240NULL', 'instantaneous', 'This spell will kill 3d12 hit dice or levels of creatures in a 30NULL radius sphere centered wherever the caster wishes (within the range limit). Excess levels of effectiveness are lost. Each creature affected is allowed to save vs. Death Ray; those that fail the save die immediately. Creatures of 8 or more hit dice or levels are immune to the spell, as are undead monsters, golems, and any other "creature" that is not truly alive.', '2021-08-09 12:49:08.000+00'::timestamp, (SELECT id FROM public.ruleset WHERE name = 'Basic Fantasy Enhanced' LIMIT 1))
ON CONFLICT (id) DO UPDATE SET
  name = EXCLUDED.name,
  "range" = EXCLUDED."range",
  duration = EXCLUDED.duration,
  description = EXCLUDED.description,
  modified = EXCLUDED.modified,
  ruleset_id = EXCLUDED.ruleset_id;

INSERT INTO public.spells (id, name, "range", duration, description, modified, ruleset_id) VALUES (21, 'Detect Evil*', '60NULL', '1 round/level', 'This spell allows the caster to detect evil; specifically, the caster can detect creatures with evil intentions, magic items with evil enchantments, and possibly extraplanar creatures of evil nature. Normal characters, even "bad" characters, cannot be detected by this spell, as only overwhelming evil is detectable. The caster sees the ???evil"?? creatures or objects with a definite glow around them, but the glow cannot be seen by anyone else.

The exact definition of evil is left for the GM to decide. Note that items such as ordinary traps or poisons are not "evil," and thus not detectable by this spell.

Reversed, this spell becomes detect good, which works just as described above with respect to detecting "good" enchantments, angelic creatures, and so on.', '2021-08-09 12:49:08.000+00'::timestamp, (SELECT id FROM public.ruleset WHERE name = 'Basic Fantasy Enhanced' LIMIT 1))
ON CONFLICT (id) DO UPDATE SET
  name = EXCLUDED.name,
  "range" = EXCLUDED."range",
  duration = EXCLUDED.duration,
  description = EXCLUDED.description,
  modified = EXCLUDED.modified,
  ruleset_id = EXCLUDED.ruleset_id;

INSERT INTO public.spells (id, name, "range", duration, description, modified, ruleset_id) VALUES (22, 'Detect Invisible', '60NULL', '1 turn/level', 'By means of this spell the caster is able to see invisible characters, creatures or objects within the given range, seeing them as translucent shapes.', '2021-08-09 00:56:52.000+00'::timestamp, (SELECT id FROM public.ruleset WHERE name = 'Basic Fantasy Enhanced' LIMIT 1))
ON CONFLICT (id) DO UPDATE SET
  name = EXCLUDED.name,
