  modified = EXCLUDED.modified,
  ruleset_id = EXCLUDED.ruleset_id;

INSERT INTO public.spells (id, name, "range", duration, description, modified, ruleset_id) VALUES (81, 'Shield', '297-TRIAL-self 12', '286-TRIAL-5 rounds+1/level 90', 'Shield creates an invisible, shield-like mobile disk of force that hovers in front of the caster. It negates magic missile attacks directed at the caster, and improves the casterNULLs Armor Class by +3 vs. melee attacks and +6 vs. missile weapons. The Armor Class benefits do not apply to attacks originating from behind the caster, but magic missiles are warded off from all directions.', '2021-08-09 00:56:52.000+00'::timestamp, (SELECT id FROM public.ruleset WHERE name = 'Basic Fantasy Enhanced' LIMIT 1))
ON CONFLICT (id) DO UPDATE SET
  name = EXCLUDED.name,
