  ruleset_id = EXCLUDED.ruleset_id;

INSERT INTO public.spells (id, name, "range", duration, description, modified, ruleset_id) VALUES (82, 'Silence 15NULL Radius', '161-TRIAL-360NULL 36', '155-TRIAL-2 rounds/level 167', 'Upon the casting of this spell, complete silence prevails within a 15NULL radius around the target. All sound is stopped: Conversation is impossible, spells cannot be cast, and no noise whatsoever issues from, enters, or passes through the area. The spell can be cast on a point in space, making the effect stationary, or it may be cast on a mobile object. The spell can be centered on a creature, and the effect then radiates from the creature and moves as it moves. An unwilling creature receives a save vs. Spells to negate the spell. If an item in another creatureNULLs possession is targeted, that creature also receives a save vs. Spells to negate. This spell provides a defense against sonic or language-based attacks or spells.', '2021-08-09 00:56:52.000+00'::timestamp, (SELECT id FROM public.ruleset WHERE name = 'Basic Fantasy Enhanced' LIMIT 1))
ON CONFLICT (id) DO UPDATE SET
  name = EXCLUDED.name,
  "range" = EXCLUDED."range",
