  modified = EXCLUDED.modified,
  ruleset_id = EXCLUDED.ruleset_id;

INSERT INTO public.spells (id, name, "range", duration, description, modified, ruleset_id) VALUES (91, 'Telekinesis', '162-TRIAL-self 155', '10-TRIAL-3 turns 59', 'This spell permits the caster to move objects or creatures by concentration alone. An object weighing no more than 50 pounds per caster level can be moved up to 20 feet per round. A creature can negate the effect on itself or an object it holds or has on its body with a successful save vs. Death Ray. In order to use this power, the caster must maintain concentration, moving no more than normal movement (no running), making no attacks and casting no spells. If concentration is lost (whether intentional or not), the power may be used again on the next round, but the subject of the effect is allowed a new saving throw.', '2021-08-09 00:56:52.000+00'::timestamp, (SELECT id FROM public.ruleset WHERE name = 'Basic Fantasy Enhanced' LIMIT 1))
ON CONFLICT (id) DO UPDATE SET
  name = EXCLUDED.name,
  "range" = EXCLUDED."range",
  duration = EXCLUDED.duration,
