  ruleset_id = EXCLUDED.ruleset_id;

INSERT INTO public.spells (id, name, "range", duration, description, modified, ruleset_id) VALUES (94, 'Ventriloquism', '91-TRIAL-60NULL 236', '74-TRIAL-1 turn/level 220', 'This spell allows the caster to cause his or her voice to sound from someplace else within range, for example, from a dark alcove or statue.', '2021-08-09 00:56:52.000+00'::timestamp, (SELECT id FROM public.ruleset WHERE name = 'Basic Fantasy Enhanced' LIMIT 1))
