  modified = EXCLUDED.modified,
  ruleset_id = EXCLUDED.ruleset_id;

INSERT INTO public.spells (id, name, "range", duration, description, modified, ruleset_id) VALUES (98, 'Water Breathing', '0-TRIAL-touch 188', '127-TRIAL-2 hours/level 167', 'The affected creatures can breathe water freely. Divide the duration evenly among all the creatures the caster touches. The spell does not make creatures unable to breathe air.', '2021-08-09 00:56:52.000+00'::timestamp, (SELECT id FROM public.ruleset WHERE name = 'Basic Fantasy Enhanced' LIMIT 1))
