INSERT INTO public.spells (id, name, "range", duration, description, modified, ruleset_id) VALUES (101, 'Wizard Lock', '13-TRIAL-20NULL 214', '209-TRIAL-permanent 116', 'A wizard lock spell cast upon a door, chest, or portal magically locks it. The caster can freely pass his or her own wizard lock without affecting it, as can any Magic-User 3 or more levels higher than the caster of the wizard lock; otherwise, a door or object secured with this spell can be opened only by breaking in or with a successful dispel magic or knock spell.', '2021-08-09 00:56:52.000+00'::timestamp, (SELECT id FROM public.ruleset WHERE name = 'Basic Fantasy Enhanced' LIMIT 1))
ON CONFLICT (id) DO UPDATE SET
