  "range" = EXCLUDED."range",
  duration = EXCLUDED.duration,
  description = EXCLUDED.description,
  modified = EXCLUDED.modified,
  ruleset_id = EXCLUDED.ruleset_id;

INSERT INTO public.spells (id, name, "range", duration, description, modified, ruleset_id) VALUES (104, 'Animate Natural Objects', '224-TRIAL- 100NULL+10NULL/level 208', '144-TRIAL- 1 round/level 209', 'This spell functions identically to the cleric spell animate objects, but it may only be cast on living trees, plants, or fungi, wooden objects, un-worked stone or earth, or naturally-occurring bodies of water or ice. At the GMNULLs option other natural phenomena such as non-magical fires or weather effects might also be subject to this spell.', '2021-08-09 00:56:52.000+00'::timestamp, (SELECT id FROM public.ruleset WHERE name = 'Basic Fantasy Enhanced' LIMIT 1))
