INSERT INTO public.spells (id, name, "range", duration, description, modified, ruleset_id) VALUES (109, 'Control Temperature, 10NULL Radius', '98-TRIAL- 0NULL 281', '89-TRIAL- 1 hour/level 98', 'The caster can change automatically the surrounding temperature (10 ft radius sphere) by up to 10 degrees Fahrenheit per caster level. The change can be upward or downward (casterNULLs choice).', '2021-08-09 00:56:52.000+00'::timestamp, (SELECT id FROM public.ruleset WHERE name = 'Basic Fantasy Enhanced' LIMIT 1))
