INSERT INTO public.spells (id, name, "range", duration, description, modified, ruleset_id) VALUES (114, 'Flame Strike', '2-TRIAL- 60NULL 234', '272-TRIAL- instantaneous 255', 'A flame strike produces a vertical column of divine fire roaring downward (cylinder of 10 ft radius, 30 ft high). The spell deals 6d8 points of damage to any creatures within the area of effect; a save vs. Spells for half damage is allowed.', '2021-08-09 00:56:52.000+00'::timestamp, (SELECT id FROM public.ruleset WHERE name = 'Basic Fantasy Enhanced' LIMIT 1))
