  modified = EXCLUDED.modified,
  ruleset_id = EXCLUDED.ruleset_id;

INSERT INTO public.spells (id, name, "range", duration, description, modified, ruleset_id) VALUES (116, 'Hold Animal', '275-TRIAL- 180NULL 233', '169-TRIAL- 2d8 turns 42', 'This spell functions like hold person, except that it affects only animals; specifically, this means non-magical living creatures of animal intelligence, including giant-sized animals. A save vs. Spells is allowed to resist this spell.', '2021-08-09 00:56:52.000+00'::timestamp, (SELECT id FROM public.ruleset WHERE name = 'Basic Fantasy Enhanced' LIMIT 1))
