INSERT INTO public.spells (id, name, "range", duration, description, modified, ruleset_id) VALUES (117, 'Obscuring Mist', '144-TRIAL- 20NULL radius 216', '281-TRIAL- 1 turn/level 198', 'This spell causes a bank of misty vapor to arise around the caster, remaining stationary once created. The vapor obscures all sight, including darkvision, beyond 2d4 ft. A strong wind can disperse the spell in one-quarter the usual duration', '2021-08-09 00:56:52.000+00'::timestamp, (SELECT id FROM public.ruleset WHERE name = 'Basic Fantasy Enhanced' LIMIT 1))
