INSERT INTO public.spells (id, name, "range", duration, description, modified, ruleset_id) VALUES (118, 'Part Water', '122-TRIAL- 60NULL 51', '121-TRIAL- 1 turn/level 299', 'This spell, when cast on a body of water, causes it to part. This exposes a path that can be traversed as if it where dry land. Note that this spell does not change the topography of the bottom of the body of water, so the terrain my still be difficult to cross. The caster is able to affect a body of water up to 5 ft./caster level. The caster may dismiss this spell at any time.', '2021-08-09 00:56:53.000+00'::timestamp, (SELECT id FROM public.ruleset WHERE name = 'Basic Fantasy Enhanced' LIMIT 1))
