INSERT INTO public.spells (id, name, "range", duration, description, modified, ruleset_id) VALUES (119, 'Pass Tree', '257-TRIAL- Touch 276', '292-TRIAL- Instantaneous 89', 'This spell allows the caster and up to two others to teleport between any two living trees on the same plane. The caster chooses a general location or a specific tree. The caster must have personal knowledge of the specific tree or general area of the target destination.', '2021-08-09 00:56:53.000+00'::timestamp, (SELECT id FROM public.ruleset WHERE name = 'Basic Fantasy Enhanced' LIMIT 1))
