INSERT INTO public.spells (id, name, "range", duration, description, modified, ruleset_id) VALUES (120, 'Pass Without Trace', '275-TRIAL- Touch 212', '200-TRIAL- 1 hour/level 110', 'This spell permits up to one creature per caster level to move through any type of terrain, leaving neither footprints nor scent. Tracking the subjects by non-magical means is thus rendered impossible.', '2021-08-09 00:56:53.000+00'::timestamp, (SELECT id FROM public.ruleset WHERE name = 'Basic Fantasy Enhanced' LIMIT 1))
