  description = EXCLUDED.description,
  modified = EXCLUDED.modified,
  ruleset_id = EXCLUDED.ruleset_id;

INSERT INTO public.spells (id, name, "range", duration, description, modified, ruleset_id) VALUES (123, 'Protection From Lightning', '202-TRIAL- Touch 85', '182-TRIAL- special 85', 'This spell functions exactly like protection from fire, except that that it protects against any sort of electrical or lightning damage.', '2021-08-09 00:56:53.000+00'::timestamp, (SELECT id FROM public.ruleset WHERE name = 'Basic Fantasy Enhanced' LIMIT 1))
