  modified = EXCLUDED.modified,
  ruleset_id = EXCLUDED.ruleset_id;

INSERT INTO public.spells (id, name, "range", duration, description, modified, ruleset_id) VALUES (125, 'Slow Poison', '232-TRIAL- Touch 32', '269-TRIAL- 1 hour/level 54', 'The creature touched by the caster becomes temporarily immune to poison. Any poison in its system or any poison to which it is exposed during the spellNULLs duration does not affect the subject until the spellNULLs duration has expired. Slow poison does not cure any damage that poison may have already done, with exception of the following circumstances.', '2021-08-09 00:56:53.000+00'::timestamp, (SELECT id FROM public.ruleset WHERE name = 'Basic Fantasy Enhanced' LIMIT 1))
