INSERT INTO public.spells (id, name, "range", duration, description, modified, ruleset_id) VALUES (126, 'Summon Animals I', '221-TRIAL- 40NULL/level 89', '176-TRIAL- One hour 129', 'This spell summons 1d8 ordinary animals (including giant ones) of no more than 4 HD each if they are within range. The Druid must name the type of animal summoned, and can have up to three choices. If none of the three species are found within range, the spell fails. The animals will be friendly when summoned and aid the DruidNULLs current task, including combat, in whatever way they can (to the best of their understanding). The Druid may dismiss any animals called by this spell at any time.', '2021-08-09 00:56:53.000+00'::timestamp, (SELECT id FROM public.ruleset WHERE name = 'Basic Fantasy Enhanced' LIMIT 1))
