INSERT INTO public.spells (id, name, "range", duration, description, modified, ruleset_id) VALUES (128, 'Summon Animals III', '134-TRIAL- 80NULL/level 49', '241-TRIAL- One day 212', 'This spell is a more powerful version of Summon Animals II. Up to 4d6 animals of 4 HD or less can be summoned, or 3d4 animals of 8 HD or less, or 1d4 animals of 12 HD or less.', '2021-08-09 00:56:53.000+00'::timestamp, (SELECT id FROM public.ruleset WHERE name = 'Basic Fantasy Enhanced' LIMIT 1))
