INSERT INTO public.spells (id, name, "range", duration, description, modified, ruleset_id) VALUES (131, 'Weather Summoning', '187-TRIAL- 10 miles 229', '49-TRIAL- 5 turns/level 37', 'The caster is able to summon nearby weather conditions. The caster must be aware of the weather condition to summon it. This spell does not grant control of the weather to the caster.', '2021-08-09 00:56:53.000+00'::timestamp, (SELECT id FROM public.ruleset WHERE name = 'Basic Fantasy Enhanced' LIMIT 1))
