INSERT INTO public.spells (id, name, "range", duration, description, modified, ruleset_id) VALUES (132, 'Advanced Illusion', '66-TRIAL-180NULL 49', '193-TRIAL-1 minute / level 95', 'This spell functions like the spell spectral force except that the illusion follows a script determined by the caster. The illusion follows the script without requiring the caster to concentrate on it. If the illusion includes intelligible speech, however, such speech is likewise scripted, so the illusion will not respond if spoken to.', '2021-08-09 00:56:53.000+00'::timestamp, (SELECT id FROM public.ruleset WHERE name = 'Basic Fantasy Enhanced' LIMIT 1))
