  description = EXCLUDED.description,
  modified = EXCLUDED.modified,
  ruleset_id = EXCLUDED.ruleset_id;

INSERT INTO public.spells (id, name, "range", duration, description, modified, ruleset_id) VALUES (145, 'Gaze Reflection', '286-TRIAL-0 213', '274-TRIAL-1 round / level 122', 'The spell creates a mirror like image in the air in front of the casterNULLs face. Any gaze attack, such as that from a basilisk or a medusa, will be reflected back upon the attacker when it looks at the caster.', '2021-08-09 00:56:53.000+00'::timestamp, (SELECT id FROM public.ruleset WHERE name = 'Basic Fantasy Enhanced' LIMIT 1))
ON CONFLICT (id) DO UPDATE SET
  name = EXCLUDED.name,
