INSERT INTO public.spells (id, name, "range", duration, description, modified, ruleset_id) VALUES (149, 'Improved Invisibility', '234-TRIAL-touch 74', '72-TRIAL-1 round / level 59', 'This spell works exactly like invisibility, except that it does not end if the subject attacks or casts a spell.', '2021-08-09 00:56:53.000+00'::timestamp, (SELECT id FROM public.ruleset WHERE name = 'Basic Fantasy Enhanced' LIMIT 1))
ON CONFLICT (id) DO UPDATE SET
