INSERT INTO public.spells (id, name, "range", duration, description, modified, ruleset_id) VALUES (150, 'Mass Invisibility', '133-TRIAL-240NULL 170', '287-TRIAL-special 97', 'This spell bestows the effect of an invisibility spell on all creatures within a 30NULL by 30NULL area, exactly as if each such creature had received its own spell; thus, each subject will remain invisible until he or she attacks or casts a spell, and will remain invisible after leaving the area of effect.  As with the normal invisibility spell, this spell lasts at most 24 hours.', '2021-08-09 23:15:33.000+00'::timestamp, (SELECT id FROM public.ruleset WHERE name = 'Basic Fantasy Enhanced' LIMIT 1))
ON CONFLICT (id) DO UPDATE SET
  name = EXCLUDED.name,
