INSERT INTO public.spells (id, name, "range", duration, description, modified, ruleset_id) VALUES (151, 'Mass Suggestion', '18-TRIAL-30NULL 77', '73-TRIAL-up to 1 hour / level 170', 'This spell bestows the effect of a suggestion spell on all creatures within a 30-foot by 30-foot area. The single suggestion applies to all of the targets. Each target gets its own saving throw.', '2021-08-09 00:56:53.000+00'::timestamp, (SELECT id FROM public.ruleset WHERE name = 'Basic Fantasy Enhanced' LIMIT 1))
