INSERT INTO public.spells (id, name, "range", duration, description, modified, ruleset_id) VALUES (168, 'Shadow Door', '100-TRIAL-10NULL 87', '160-TRIAL-1 round / level 126', 'The caster creates the illusion of a door, which he or she will appear to pass through and close. In reality, the caster becomes invisible (as the spell) when the spell is cast. Any creatures opening the "door" will see an empty 10-foot square room, of similar style to the surrounding area. The caster remains invisible for the duration of the spell, unless, as with an invisibility spell, he or she attacks any creature or casts a spell.', '2021-08-09 12:49:08.000+00'::timestamp, (SELECT id FROM public.ruleset WHERE name = 'Basic Fantasy Enhanced' LIMIT 1))
ON CONFLICT (id) DO UPDATE SET
  name = EXCLUDED.name,
