  modified = EXCLUDED.modified,
  ruleset_id = EXCLUDED.ruleset_id;

INSERT INTO public.spells (id, name, "range", duration, description, modified, ruleset_id) VALUES (172, 'Stinking Cloud', '165-TRIAL-100NULL +10NULL / level 187', '177-TRIAL-10 rounds / level 74', 'The spell functions like obscurement, but any living creature in the cloud becomes nauseated such that they may not attack, concentrate, cast spells, or do anything other than move. A creature remains nauseated as long as the creature is in the cloud and for 1d4 + 1 rounds after leaving the cloud. A creature may save vs. Spells to avoid the effect of the cloud, but must save every round they remain in the cloud.', '2021-08-09 00:56:53.000+00'::timestamp, (SELECT id FROM public.ruleset WHERE name = 'Basic Fantasy Enhanced' LIMIT 1))
ON CONFLICT (id) DO UPDATE SET
