  ruleset_id = EXCLUDED.ruleset_id;

INSERT INTO public.spells (id, name, "range", duration, description, modified, ruleset_id) VALUES (174, 'Veil', '223-TRIAL-400NULL radius 20', '2-TRIAL-1 hour / level 262', 'This spell works as change self, but instead can affect any number of willing creatures within the given range. The caster may choose which creatures are affected and may include themselves.', '2021-08-09 00:56:53.000+00'::timestamp, (SELECT id FROM public.ruleset WHERE name = 'Basic Fantasy Enhanced' LIMIT 1))
