INSERT INTO public.spells (id, name, "range", duration, description, modified, ruleset_id) VALUES (177, 'Boneskin', '202-TRIAL-self 16', '230-TRIAL-1 turn / level 226', 'Protects the caster; the caster manifests a chitinous bone-like armor, giving the caster a +4 bonus to AC. No actual bulk is added to the caster, so it doesnNULLt affect other spell-casting.', '2021-08-09 00:56:53.000+00'::timestamp, (SELECT id FROM public.ruleset WHERE name = 'Basic Fantasy Enhanced' LIMIT 1))
ON CONFLICT (id) DO UPDATE SET
