  ruleset_id = EXCLUDED.ruleset_id;

INSERT INTO public.spells (id, name, "range", duration, description, modified, ruleset_id) VALUES (178, 'Call Poltergeist', '211-TRIAL-5NULL / level 171', '111-TRIAL-1 hour / level 47', 'This spell binds a minor spirit to an area. The poltergeist is an invisible, shapeless force that performs simple tasks at the NecromancerNULLs command. A poltergeist can run and fetch things, open unstuck doors, and hold chairs, as well as clean and mend. The poltergeist can perform only one activity at a time, but it repeats the same activity over and over again if told to do so as long as the Necromancer remains within range. A poltergeist can only open normal doors, drawers, lids, and the like, having an effective Strength score of 3. The poltergeist can trigger traps and such, but it can exert only 20 pounds of force, which may not be enough to activate certain pressure plates and other devices.', '2021-08-09 00:56:53.000+00'::timestamp, (SELECT id FROM public.ruleset WHERE name = 'Basic Fantasy Enhanced' LIMIT 1))
ON CONFLICT (id) DO UPDATE SET
  name = EXCLUDED.name,
  "range" = EXCLUDED."range",
  duration = EXCLUDED.duration,
  description = EXCLUDED.description,
  modified = EXCLUDED.modified,
  ruleset_id = EXCLUDED.ruleset_id;

INSERT INTO public.spells (id, name, "range", duration, description, modified, ruleset_id) VALUES (179, 'Chill', '153-TRIAL-10NULL 220', '90-TRIAL-2 rounds 224', 'This spell does 1d4 points of damage to one creature within range. Furthermore, the creature must save vs. Paralysis or suffer -1 to melee hit and damage rolls for 1d6 rounds. A large heat source nearby gives a +2 to save. The caster may use this spell on one target up to 2 rounds after casting.', '2021-08-09 00:56:53.000+00'::timestamp, (SELECT id FROM public.ruleset WHERE name = 'Basic Fantasy Enhanced' LIMIT 1))
ON CONFLICT (id) DO UPDATE SET
