  modified = EXCLUDED.modified,
  ruleset_id = EXCLUDED.ruleset_id;

INSERT INTO public.spells (id, name, "range", duration, description, modified, ruleset_id) VALUES (180, 'Command Undead', '188-TRIAL-30NULL 163', '140-TRIAL-special 151', 'This spell allows the caster to influence an undead creature. If the undead creature is intelligent, this spell operates as charm person, except that the caster can influence 2 HD per caster level, instead of just a flat 4 HD. It otherwise operates the same, including duration.

If the undead creature is unintelligent, the caster immediately gains complete control, the creature gets no saving throw, and the duration is permanent. Any unintelligent undead controlled using this spell count against the total control limit from re-animation.', '2021-08-09 12:44:19.000+00'::timestamp, (SELECT id FROM public.ruleset WHERE name = 'Basic Fantasy Enhanced' LIMIT 1))
ON CONFLICT (id) DO UPDATE SET
  name = EXCLUDED.name,
  "range" = EXCLUDED."range",
