INSERT INTO public.spells (id, name, "range", duration, description, modified, ruleset_id) VALUES (194, 'Halt Undead', '185-TRIAL-360NULL 41', '123-TRIAL-1 round / level 129', 'This spell will render up to three undead creatures immobile for the duration of the spell (similar to hold person, but only affecting undead and potentially affecting more than one target). Intelligent undead get a save vs. Spells to avoid; unintelligent undead get no saving throw.', '2021-08-09 00:56:53.000+00'::timestamp, (SELECT id FROM public.ruleset WHERE name = 'Basic Fantasy Enhanced' LIMIT 1))
