INSERT INTO public.spells (id, name, "range", duration, description, modified, ruleset_id) VALUES (196, 'Mask of Life', '96-TRIAL-touch 155', '53-TRIAL-1 hour / level 162', 'This spell makes a single undead creature appear to be alive. The caster can decide which race and style of clothes is worn by an undead creature. The spell will also make the targetNULLs movements appear life-like. The illusion will create appropriate ambient effects (smells, sounds, clothing textures, and such) that would be expected for the life-like', '2021-08-09 00:56:53.000+00'::timestamp, (SELECT id FROM public.ruleset WHERE name = 'Basic Fantasy Enhanced' LIMIT 1))
