INSERT INTO public.spells (id, name, "range", duration, description, modified, ruleset_id) VALUES (200, 'Ray of Exhaustion', '167-TRIAL-50NULL 48', '175-TRIAL-6 rounds / level 38', 'The caster points a finger at his or her intended target and rolls a ranged attack roll against the target that ignores armor (but not any dexterity bonus). If the narrow black ray hits, the target must save vs. Spells or suffer a -6 adjustment to its Strength and Dexterity for the duration of the spell. If the save is made, the reduction is only -2.', '2021-08-09 00:56:53.000+00'::timestamp, (SELECT id FROM public.ruleset WHERE name = 'Basic Fantasy Enhanced' LIMIT 1))
