  ruleset_id = EXCLUDED.ruleset_id;

INSERT INTO public.spells (id, name, "range", duration, description, modified, ruleset_id) VALUES (202, 'Rot Flesh', '241-TRIAL-touch 75', '159-TRIAL-instantaneous 125', 'This spell works exactly like the decay flesh spell, save that it deals 2d6 points of damage plus 1 point per caster level to the creature affected by it. The caster must make a successful attack to inflict the damage. A missed attack roll does not dispel the effect, as it can be active until used or a number of rounds equal to the casterNULLs level have passed.

Just like the lower level decay flesh spell, this spell may not be reversed, and similarly, this spell works upon undead creatures in the opposite fashion; they are healed for 2d6 points plus 1 point per caster level worth of damage instead.', '2021-08-09 12:45:02.000+00'::timestamp, (SELECT id FROM public.ruleset WHERE name = 'Basic Fantasy Enhanced' LIMIT 1))
