  modified = EXCLUDED.modified,
  ruleset_id = EXCLUDED.ruleset_id;

INSERT INTO public.spells (id, name, "range", duration, description, modified, ruleset_id) VALUES (206, 'Symbol of Fear', '79-TRIAL-see text 201', '193-TRIAL-see text 134', 'This spell functions like symbol of pain, except that all creatures within 60 feet of the symbol of fear become panicked for 1 round per caster level. A panicked creature will drop whatever it is holding and flee using any means necessary. If cornered, the creature will cower in fear. The victim will also suffer a -2 to all saving throws. The creature will do this for the duration of the spell. If a save is made, the victim is still shaken and suffers -2 to attack rolls and saving throws for 1 round.', '2021-08-09 00:56:53.000+00'::timestamp, (SELECT id FROM public.ruleset WHERE name = 'Basic Fantasy Enhanced' LIMIT 1))
