INSERT INTO public.spells (id, name, "range", duration, description, modified, ruleset_id) VALUES (212, 'Waves of Fatigue', '252-TRIAL-30NULL 143', '96-TRIAL-1 turn / level 73', 'This spell sends an invisible wave of harmful energy out forward of the caster to a range of 30 feet. All living creatures in the area suffer a -2 adjustment to their Strength and Dexterity for the duration of the spell.', '2021-08-09 00:56:53.000+00'::timestamp, (SELECT id FROM public.ruleset WHERE name = 'Basic Fantasy Enhanced' LIMIT 1))
