  modified = EXCLUDED.modified,
  ruleset_id = EXCLUDED.ruleset_id;

INSERT INTO public.spells (id, name, "range", duration, description, modified, ruleset_id) VALUES (216, 'Barkskin', '240-TRIAL- self 88', '185-TRIAL- 1 turn/level 190', 'Protects the caster. The casterNULLs skin turns hard and bark-like, giving the caster a +4 bonus to AC. No actual bulk is added to the caster, so it doesnNULLt affect other spell casting..', '2021-08-10 00:15:09.000+00'::timestamp, (SELECT id FROM public.ruleset WHERE name = 'Basic Fantasy Enhanced' LIMIT 1))
