INSERT INTO public.spells (id, name, "range", duration, description, modified, ruleset_id) VALUES (219, 'Changestaff', '144-TRIAL-touch 158', '35-TRIAL-1 hour/level 59', 'This spell transforms a specially prepared staff into a treant-like creature. The creature looks and fights just like a treant, and will follow all directions given by the caster. The creature is not an actual treant, and so cannot talk to other treants or animate trees. If the creature is reduced to 0 hit points, it disintegrates and the staff is destroyed. If the duration expires, or the caster ends the spell early, the creatures transforms back into the staff.', '2021-08-10 00:15:09.000+00'::timestamp, (SELECT id FROM public.ruleset WHERE name = 'Basic Fantasy Enhanced' LIMIT 1))
