  "range" = EXCLUDED."range",
  duration = EXCLUDED.duration,
  description = EXCLUDED.description,
  modified = EXCLUDED.modified,
  ruleset_id = EXCLUDED.ruleset_id;

INSERT INTO public.spells (id, name, "range", duration, description, modified, ruleset_id) VALUES (230, 'Finger of Death', '204-TRIAL-60NULL 203', '221-TRIAL-instanteous 163', 'The caster points their finger at one creature, who must then save vs. Death Ray or instantly die. If they make their saving throw, they still take 3d6 + 1 point per caster level of damage.

This spell only affects living creatures and does not affect non-living creatures like constructs or undead.', '2021-08-10 00:15:09.000+00'::timestamp, (SELECT id FROM public.ruleset WHERE name = 'Basic Fantasy Enhanced' LIMIT 1))
