INSERT INTO public.spells (id, name, "range", duration, description, modified, ruleset_id) VALUES (231, 'Fire Storm', '6-TRIAL-100NULL+10NULL/level 263', '10-TRIAL-instanteous 271', 'This spell causes an area 20NULLx10NULLx10NULL per caster level to be filled with holy fire. The caster can determine the shape of the area, but the entire area must be contiguous. Any creature in the designated area takes 1d6 points of damage that bypasses any immunity or resistance to fire. Any creature that dies from the damage (or was already', '2021-08-10 00:15:09.000+00'::timestamp, (SELECT id FROM public.ruleset WHERE name = 'Basic Fantasy Enhanced' LIMIT 1))
