INSERT INTO public.spells (id, name, "range", duration, description, modified, ruleset_id) VALUES (234, 'Gentle Repose', '18-TRIAL-touch 232', '150-TRIAL-1 day/level 5', 'This spell preserves the remains of a dead creature (including a zombie, if so desired). This prevents any decay of the remains for the duration of the spell. This extends the time limit imposed by raise dead, allowing for a longer time to cast the spells.', '2021-08-10 00:15:09.000+00'::timestamp, (SELECT id FROM public.ruleset WHERE name = 'Basic Fantasy Enhanced' LIMIT 1))
