INSERT INTO public.spells (id, name, "range", duration, description, modified, ruleset_id) VALUES (236, 'Greater Teleport', '98-TRIAL- self 147', '84-TRIAL- instantaneous 148', 'This spell functions in a similar fashion to the normal teleport spell, except that there is no limit to the range that can be spanned, nor is there any chance of arriving off target. In addition, the caster need not have seen the', '2021-08-10 00:15:09.000+00'::timestamp, (SELECT id FROM public.ruleset WHERE name = 'Basic Fantasy Enhanced' LIMIT 1))
