INSERT INTO public.spells (id, name, "range", duration, description, modified, ruleset_id) VALUES (239, 'Insanity', '269-TRIAL-100NULL+10NULL/level 262', '119-TRIAL-instantaneous 185', 'The target of this spell must save vs. Spells or be permanently under the effects of the confusion spell. The only way to remove this condition is through the use of heal, restoration, or a wish. (Remove curse or dispel magic will not remove this condition.) If the save is made, the confusion still lasts for 2 rounds + 1 round per caster level.', '2021-08-10 00:15:09.000+00'::timestamp, (SELECT id FROM public.ruleset WHERE name = 'Basic Fantasy Enhanced' LIMIT 1))
