INSERT INTO public.spells (id, name, "range", duration, description, modified, ruleset_id) VALUES (241, 'Mage Armor', '145-TRIAL-self 8', '118-TRIAL-1 turn 270', 'Protects the caster. The caster&apos;s skin becomes hard and stone-like, giving the caster a +2 bonus to armor class vs. melee attacks and hand-thrown missiles such as daggers or spears, and a +4 bonus to armor class vs. normal sized projectiles such as arrows, bolts, sling stones, and sling bullets.', '2021-08-10 00:15:09.000+00'::timestamp, (SELECT id FROM public.ruleset WHERE name = 'Basic Fantasy Enhanced' LIMIT 1))
