INSERT INTO public.spells (id, name, "range", duration, description, modified, ruleset_id) VALUES (250, 'Remove Paralysis', '254-TRIAL-touch 188', '46-TRIAL-instantaneous 90', 'This spell permits the caster to free the creature touched from paralysis induced either by magical means or by monster attack (e.g. venom or ghouls).', '2021-08-10 00:15:09.000+00'::timestamp, (SELECT id FROM public.ruleset WHERE name = 'Basic Fantasy Enhanced' LIMIT 1))
