  modified = EXCLUDED.modified,
  ruleset_id = EXCLUDED.ruleset_id;

INSERT INTO public.spells (id, name, "range", duration, description, modified, ruleset_id) VALUES (258, 'Shades', '49-TRIAL-30NULL 196', '284-TRIAL-1 turn/level 215', 'This spell summons a shade creature. A shade creature is the same as a shadow monster from the Basic Fantasy RPG Core Rules, except that it has 9 HD and does 1d8 damage (cold), plus drains 1 point of strength. An opponent killed by strength damage will not rise as a new shade creature or shadow, but will merely be dead. A shade creature obeys the casterNULLs orders without question and can understand the casterNULLs language.', '2021-08-10 00:15:09.000+00'::timestamp, (SELECT id FROM public.ruleset WHERE name = 'Basic Fantasy Enhanced' LIMIT 1))
ON CONFLICT (id) DO UPDATE SET
  name = EXCLUDED.name,
