INSERT INTO public.spells (id, name, "range", duration, description, modified, ruleset_id) VALUES (259, 'Shillelagh', '264-TRIAL- touch 242', '275-TRIAL- 1 minute/level 213', 'This turns any club or staff wielded by the caster into a magical weapon with a +1 bonus to hit and to damage. The club or staff also does 1d8 points of damage instead of its normal damage. This spell only affects a weapon held by the caster. If the caster releases the weapon, the benefits no longer apply, but, if the caster retrieves the weapon prior to the end of the spell, the benefits result until the spell ends.', '2021-08-10 00:15:09.000+00'::timestamp, (SELECT id FROM public.ruleset WHERE name = 'Basic Fantasy Enhanced' LIMIT 1))
ON CONFLICT (id) DO UPDATE SET
