INSERT INTO public.spells (id, name, "range", duration, description, modified, ruleset_id) VALUES (261, 'Stoneskin', '26-TRIAL-touch 206', '73-TRIAL-1 turn/level 129', 'Protects the caster. The caster&apos;s skin becomes hard and stone-like, protecting the caster by absorbing the first 10 points of damage from all attacks. (This operates like hardness.) Once the spell has absorbed 10 points of damage per caster level, the spell is discharged.', '2021-08-10 00:15:09.000+00'::timestamp, (SELECT id FROM public.ruleset WHERE name = 'Basic Fantasy Enhanced' LIMIT 1))
ON CONFLICT (id) DO UPDATE SET
