  description = EXCLUDED.description,
  modified = EXCLUDED.modified,
  ruleset_id = EXCLUDED.ruleset_id;

INSERT INTO public.spells (id, name, "range", duration, description, modified, ruleset_id) VALUES (265, 'Tree', '156-TRIAL- self 52', '236-TRIAL- 1 hour/level 238', 'This spell allows the caster to assume the form of a tree. The tree may be either a small living tree or shrub, or a large dead tree with few limbs. All inspection of the tree will show it to only be a tree, and even detect magic will return inconclusive results. While in the form of a tree, the caster can see and hear all around them and is fully aware of their environment. The casterNULLs hit points and saving throws are unchanged, and a +10 bonus to armor class is gained. All clothing and gear worn is transformed with the caster. The spell may be dismissed at any time prior to the end of the spell.', '2021-08-10 00:15:09.000+00'::timestamp, (SELECT id FROM public.ruleset WHERE name = 'Basic Fantasy Enhanced' LIMIT 1))
