INSERT INTO public.spells (id, name, "range", duration, description, modified, ruleset_id) VALUES (266, 'Unseen Servant', '82-TRIAL-50NULL 155', '15-TRIAL-1 hour/level 231', 'An unseen servant is an invisible servant that is shapeless and mindless. It can be used to fetch things, return things, open doors, hold chairs, clean things, and mend things. It is not strong, having an effective strength of 3. It can only open normal doors, chests, lids, containers, and such subject to its minimal strength. The servant cannot fight, nor can it be destroyed, but it can always be dismissed at any time prior to the spellNULLs end.', '2021-08-10 00:15:09.000+00'::timestamp, (SELECT id FROM public.ruleset WHERE name = 'Basic Fantasy Enhanced' LIMIT 1))
ON CONFLICT (id) DO UPDATE SET
  name = EXCLUDED.name,
