INSERT INTO public.spells (id, name, "range", duration, description, modified, ruleset_id) VALUES (274, 'Meal Blessing', '100-TRIAL- 80', '18-TRIAL- 58', 'The cleric says this short prayer before a meal to give the diners a blessing. Anyone who eats the meal within twenty minutes heals 1 hit point. The meal must be normally prepared and obtained in a way that the deity permits.', '2021-08-24 06:43:57.000+00'::timestamp, (SELECT id FROM public.ruleset WHERE name = 'Basic Fantasy Enhanced' LIMIT 1))
