INSERT INTO public.spells (id, name, "range", duration, description, modified, ruleset_id) VALUES (280, 'Animate Tool', '278-TRIAL- 159', '108-TRIAL- 119', 'A single, small tool (such as a quill pen, spoon, sewing needle, or small hammer) is animated by this cantrip. It will perform a single, repetitive task (such as writing dictated words, stirring a pot of soup, sewing the hem of a dress, or nailing boards into a house) for as long as a turn. The magic user must be able to perform the repeated action by hand himself. Weapons may not be animated by this cantrip, and objects animated may not be used as weapons.', '2021-08-24 06:43:57.000+00'::timestamp, (SELECT id FROM public.ruleset WHERE name = 'Basic Fantasy Enhanced' LIMIT 1))
