INSERT INTO public.spells (id, name, "range", duration, description, modified, ruleset_id) VALUES (283, 'Flavor*', '98-TRIAL- 189', '122-TRIAL- 238', 'This cantrip may either make one dish taste any way the caster wants it to (which is an illusion), or add salt, spice, sweetener, or another flavoring agent (which is real). Reversed, it becomes Putrefy, which makes the food or drink either go bad (which is real) or taste as if it had been prepared wrongly (which is an illusion).', '2021-08-24 06:43:57.000+00'::timestamp, (SELECT id FROM public.ruleset WHERE name = 'Basic Fantasy Enhanced' LIMIT 1))
