INSERT INTO public.spells (id, name, "range", duration, description, modified, ruleset_id) VALUES (289, 'Summon Vermin*', '30-TRIAL- 39', '212-TRIAL- 188', 'This cantrip summons one small, totally ordinary insect (such as a beetle, fly, or spider), a small rodent (such as a field mouse), or a cloud of gnats into a certain area. If targeted intelligently, the spell may be able to disrupt spellcasting, but will never deal any actual damage (including poison) to the target. Reversed, this cantrip becomes Exterminate, which may kill any one creature of similar size as the ones described in the spell.', '2021-08-24 06:43:57.000+00'::timestamp, (SELECT id FROM public.ruleset WHERE name = 'Basic Fantasy Enhanced' LIMIT 1))
