INSERT INTO public.spells (id, name, "range", duration, description, modified, ruleset_id) VALUES (291, 'Bolster*', '184-TRIAL- 174', '280-TRIAL- 115', 'Undead within 10 feet of caster are harder to turn or command, being one point harder to affect (on Turning Table). The effect lasts one hour or until a Turning (or Command) attempt is made. Reversed, the cantrip makes undead one point easier for the same period.', '2021-08-24 06:43:57.000+00'::timestamp, (SELECT id FROM public.ruleset WHERE name = 'Basic Fantasy Enhanced' LIMIT 1))
