INSERT INTO public.spells (id, name, "range", duration, description, modified, ruleset_id) VALUES (292, 'Embalm', '151-TRIAL- 241', '115-TRIAL- 179', 'Specially prepares one corpse for burial (or further use). When cast upon recently dead in preparation for re-animation type spells, the newly risen Zombie will have +1 on hit point rolls for each hit die (up to maximum hit points for each hit die).', '2021-08-24 06:43:57.000+00'::timestamp, (SELECT id FROM public.ruleset WHERE name = 'Basic Fantasy Enhanced' LIMIT 1))
